// JobTitleAgent is a strongly typed Agent definition that can
// be imported and directly referenced in feature code
export const JobTitleAgent = defineAgent({
	// Variants allow us to test and tweak anything from model,
	// hyperparameters, instructions, output schema or tools
  variants: {
    openai: defineOpenAiVariant({
      model: "gpt-4o",
      instructions: "Use the tools to determine the person's job title. If you're unsure, return null.",
      tools: [SearchTool, CurlTool],
      outputSchema: z.object({
        job_title: z.string().nullable(),
      }),
    }),

    gemini: defineVertexVariant({
      model: "gemini-1.5-flash-002",
      instructions: "Find the person's current job title using the tools provided. If unavailable, return null.",
      tools: [SearchTool, CurlTool],
      outputSchema: z.object({
        job_title: z.string().nullable(),
      }),
    }),
  },
})

await createThread({
	// Populate the thread with some content
  messages: [
    {
	    role: "user",
	    content: JSON.stringify({
		    name: "Jamie Davies",
		    company: "Attio",
	    }),
    },
  ],
  run: {
	  // Run our agent on this thread
    agent: JobTitleAgent,

    // Pick which variant to run
    // We usually inject a feature flag in here - however you 
    // could also use switch based using classic logic - e.g
    // use a more powerful model variant based on keywords
    variant: "openai",

    // Map events in the agent lifecycle to standard 
    // async task processors in the codebase -
    // the framework will automatically inject relevant generated IDs
    callbacks: [
	    {on: "complete", task: {...}},
	    {on: "failure", task: {...}}
	    {on: "tool-call", task: {...}},
    ],

    // Tell the framework how important this run is, allowing
    // the framework to prioritize and defer work.
    //
    // (It also lets us abstract over things like batch 
    // APIs - so feature code looks identical whether a
    // run takes 4 seconds or 48 hours.)
    priority: "immediate"
  },
})

